<?php
require __DIR__.'/_init.php'; require_login();
$id=(int)($_GET['id']??0); $q=db()->prepare('SELECT * FROM service_requests WHERE id=? AND user_id=?'); $q->execute([$id,$_SESSION['user']['id']]); $request=$q->fetch();
if(!$request){http_response_code(404);page_start('Request not found');echo '<div class="empty"><h1>Request not found</h1><p>This request may have been removed or belongs to another account.</p><a href="/requests.php">Back to requests</a></div>';page_end();exit;}
$q=db()->prepare('SELECT old_status,new_status,note,created_at FROM request_status_history WHERE request_id=? ORDER BY created_at DESC,id DESC');$q->execute([$id]);$history=$q->fetchAll();page_start('Request '.e($request['tracking_id']));?>
<div class="row"><div><div class="eyebrow">TRACKING ID · <?=e($request['tracking_id'])?></div><h1><?=e($request['title'])?></h1></div><a href="/requests.php">← All requests</a></div><div class="detail-grid"><section class="panel"><span class="pill"><?=e(str_replace('_',' ',$request['status']))?></span><p><?=nl2br(e($request['description']))?></p><div class="request-meta"><span>Category<strong><?=e($request['category'])?></strong></span><span>Priority<strong><?=e(ucfirst($request['priority']))?></strong></span><span>Response estimate<strong>About <?=e($request['expected_days'])?> days</strong></span></div></section><section class="panel"><h2>Status timeline</h2><ol class="timeline"><?php foreach($history as $item):?><li><b><?=e(ucwords(str_replace('_',' ',$item['new_status'])))?></b><?php if($item['note']):?><p><?=e($item['note'])?></p><?php endif;?><small><?=e($item['created_at'])?></small></li><?php endforeach;?></ol></section></div><?php page_end();?>
